style.css:
@-moz-document domain("bans.page") {
body {
        background-image: url('https://images8.alphacoders.com/678/thumb-1920-678023.jpg') !important;
        background-size: cover !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;
        color: #ffffff !important;
    }

    
    main, section, article, div, button, img {
        background-color: transparent !important;
        opacity: 1 !important;
        filter: none !important;
    }

    
    h1, h2, h3, h4, p, span, label, button, .stage-name {
        color: #ffffff !important;
        text-shadow: 1px 1px 4px rgba(0, 0, 0, 0.9) !important;
    }

    
    header, nav, .navbar {
        background-color: rgba(0, 0, 0, 0.85) !important;
        border-bottom: 2px solid #e60012 !important; 
    }

  
    header a, nav a {
        color: #ffffff !important;
    }

   
    button:hover, .stage-card:hover {
        transform: scale(1.05);
        transition: transform 0.15s ease-in-out;
    }
}
